import{_ as a,a0 as p,w as i,s as h,ao as l,I as r,x as e,a1 as o,A as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const b=JSON.parse('{"title":"10個 ssh 簡單命令選項 | LCTT x X-CMD","titleTemplate":false,"description":"10個 ssh 簡單命令選項 | LCTT (201404) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"10個 ssh 簡單命令選項 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"10個 ssh 簡單命令選項 | LCTT (201404) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201404/10 ssh options for a Secure shell for Safe Data Communication","title":"10個 ssh 簡單命令選項","tag":"201404","desc":""},"relativePath":"201404/10 ssh options for a Secure shell for Safe Data Communication.md","filePath":"[post].md"}'),c={name:"201404/10 ssh options for a Secure shell for Safe Data Communication.md"};function d(g,s,S,m,u,f){const n=p("Link");return i(),h("div",null,[s[11]||(s[11]=l(`<h1 id="_10個-ssh-簡單命令選項" tabindex="-1">10個 ssh 簡單命令選項 <a class="header-anchor" href="#_10個-ssh-簡單命令選項" aria-label="Permalink to “10個 ssh 簡單命令選項”">​</a></h1><p>一個系統管理員可能會同時管理着多台服務器，這些服務器也許會放在不同的地方。要親自一台一台的去訪問來管理它們顯然不是最好的方法，通過遠程控制的方法應該是最有效的。遠程訪問最通用的一款應用程序就是 <strong>SSH</strong>（什麼？你還用telnet？....$%@%&amp;W@$##）。</p><h3 id="ssh-是什麼" tabindex="-1">SSH 是什麼 <a class="header-anchor" href="#ssh-是什麼" aria-label="Permalink to “SSH 是什麼”">​</a></h3><p><strong>SSH（全稱 Secure Shell)</strong>是一種加密的網絡協議。使用該協議的數據將被加密，如果在傳輸中間數據泄漏，也可以確保沒有人能讀取出有用信息。要使用 SSH，目標機器應該安裝 SSH 服務端應用程序，因為 <strong>SSH 是基於客户-服務模式的。</strong> 當你想安全的遠程連接到主機，可中間的網絡（比如因特網）並不安全，通常這種情況下就會使用 SSH。</p><h3 id="安裝-ssh" tabindex="-1">安裝 SSH <a class="header-anchor" href="#安裝-ssh" aria-label="Permalink to “安裝 SSH”">​</a></h3><p>的 Linux 系統默認已經安裝了 SSH。如果碰巧你的機器沒裝（譯註：我能吐槽麼？沒有不裝ssh的Linux服務器吧，不過，大家要記得升級你的ssh服務器），我們可以手工來安裝一下。最簡單的方式就是使用 Linux 包管理器。</p><h3 id="基於-debian-ubuntu-的系統" tabindex="-1">基於 Debian / Ubuntu 的系統 : <a class="header-anchor" href="#基於-debian-ubuntu-的系統" aria-label="Permalink to “基於 Debian / Ubuntu 的系統 :”">​</a></h3><h4 id="安裝-ssh-client" tabindex="-1">安裝 ssh-client <a class="header-anchor" href="#安裝-ssh-client" aria-label="Permalink to “安裝 ssh-client”">​</a></h4><pre><code>$ sudo apt-get install openssh-client
</code></pre><h4 id="安裝-ssh-server" tabindex="-1">安裝 ssh-server <a class="header-anchor" href="#安裝-ssh-server" aria-label="Permalink to “安裝 ssh-server”">​</a></h4><pre><code>$ sudo apt-get install openssh-server
</code></pre><h3 id="基於-redhat-centos-的系統" tabindex="-1">基於 RedHat / CentOS 的系統 : <a class="header-anchor" href="#基於-redhat-centos-的系統" aria-label="Permalink to “基於 RedHat / CentOS 的系統 :”">​</a></h3><pre><code># yum install openssh-server openssh-clients
</code></pre><p>SSH 一旦安裝上，我們就可以在終端下輸入 <strong>ssh</strong> 來檢查下安裝的是否正常。</p><p><img src="http://linoxide.com/wp-content/uploads/2014/02/ssh_client.png" alt="An ssh client"></p><h3 id="使用-ssh" tabindex="-1">使用 SSH <a class="header-anchor" href="#使用-ssh" aria-label="Permalink to “使用 SSH”">​</a></h3><p>提供了許多可使用的選項。這篇文章會介紹一些我們在日常操作中經常使用的選項。</p><h4 id="_1-無選項參數運行-ssh" tabindex="-1">1. 無選項參數運行 SSH <a class="header-anchor" href="#_1-無選項參數運行-ssh" aria-label="Permalink to “1. 無選項參數運行 SSH”">​</a></h4><p>通常使用 SSH 的方式就是不加任何選項參數,僅僅輸入 &quot;<strong>ssh</strong>&quot;。下面是示例：</p><pre><code>$ ssh 192.168.0.103
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/02/ssh_ask_connect.png" alt="SSH connecti confirmation"></p><p>第一次連接目標主機時，ssh 會讓你確認目標主機的真實性。如果你回答的是 <strong>NO</strong>，SSH 將不會繼續連接，只有回答 <strong>Yes</strong> 才會繼續（譯註：會加入RSA key的指紋作為記錄，如果下次連接發現指紋變化，會提示你）。</p><p><img src="http://linoxide.com/wp-content/uploads/2014/02/ssh_connect.png" alt="Connecting to SSH"></p><p>下一次再登陸此主機時，SSH 就不會提示確認消息了。對此主機的真實驗證信息已經默認保存在每個用户的 /home/user/.ssh 文件裏。</p><h4 id="_2-指定登陸用户" tabindex="-1">2. 指定登陸用户 <a class="header-anchor" href="#_2-指定登陸用户" aria-label="Permalink to “2. 指定登陸用户”">​</a></h4><p>默認的，ssh 會嘗試用當前用户作為用户名來連接。在上面的示例命令中，ssh 會嘗試用用户名叫 pungki 的用户身份來登入服務器，這是因為用户 pungki 正在客户機上使用 ssh 客户端軟件。</p><p>假如目標主機上沒有叫 pungki 的用户呢？這時你就必須提供一個目標主機上存在的用户名。從一開始就要指定用户名的，可以使用 -l 選項參數。</p><pre><code>$ ssh -l leni 192.168.0.103
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/02/ssh_l.png" alt="Ssh using -l option"></p><p>我們也可以這樣輸入：</p><pre><code>$ ssh leni@192.168.0.0103
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/02/ssh_l_2.png" alt="Another way to supply username"></p><h4 id="_3-指定端口" tabindex="-1">3. 指定端口 <a class="header-anchor" href="#_3-指定端口" aria-label="Permalink to “3. 指定端口”">​</a></h4><p><strong>SSH 默認使用的端口號是 22。</strong>大多現代的 Linux 系統 22 端口都是開放的。如果你運行 ssh 程序而沒有指定端口號，它直接就是通過 22 端口發送請求的。</p><p>一些系統管理員會改變 SSH 的默認端口號。讓我們試試，現在端口號是 1234.要連上那主機，就要使用 *<strong>-p</strong> 選項，後面在加上 SSH 端口號。</p><pre><code>$ ssh 192.168.0.103 -p 1234
</code></pre><p>要改變端口號，我們需要修改 <strong>/etc/ssh/ssh_config</strong> 文件，找到此行：</p><pre><code>Port 22
</code></pre><p>把它換成其他的端口號，比如上面示例的 1234 端口，然後重啓 SSH 服務。</p><h4 id="_4-對所有數據請求壓縮" tabindex="-1">4.對所有數據請求壓縮 <a class="header-anchor" href="#_4-對所有數據請求壓縮" aria-label="Permalink to “4.對所有數據請求壓縮”">​</a></h4><p>有了這個選項，所有通過 SSH 發送或接收的數據將會被壓縮，並且任然是加密的。要使用 SSH 的壓縮功能，使用 <strong>-C</strong> 選項。</p><pre><code>$ ssh -C 192.168.0.103
</code></pre><p>如果你的連網速度很慢的話，比如用 modem 上網，這個選項非常有用。但如果你使用的是像 LAN 或其它更高級網絡的話，壓縮反而會降低你的傳輸速度。可以使用 <strong>-o</strong> 選項加上<strong>壓縮級別參數</strong>來控制壓縮的級別，但這個選項僅僅只在 SSH-1 下起作用。</p><h4 id="_5-指定一個加密算法" tabindex="-1">5. 指定一個加密算法 <a class="header-anchor" href="#_5-指定一個加密算法" aria-label="Permalink to “5. 指定一個加密算法”">​</a></h4><p>SSH 提供了一些可用的加密算法。可以在 **/etc/ssh/ssh_config or ~/.ssh/config ** 文件中看到（如果存在的話）。</p><p><img src="http://linoxide.com/wp-content/uploads/2014/02/ssh_cipher.png" alt="SSH cipher configuration example"></p><p>讓我們試試比如你想使用 <strong>blowfish</strong> 算法來加密你的 SSH 會話，那麼你只要把這一行加入你的 <strong>/etc/ssh/ssh_config or ~/.ssh/config</strong> 文件就可以：</p><pre><code>Cipher blowfish
</code></pre><p>默認的，SSH 會使用 3des 算法。</p><h4 id="_6-打開調試模式" tabindex="-1">6. 打開調試模式 <a class="header-anchor" href="#_6-打開調試模式" aria-label="Permalink to “6. 打開調試模式”">​</a></h4><p>因為某些原因，我們想要追蹤調試我們建立的 SSH 連接情況。SSH 提供的 <strong>-v</strong> 選項參數正是為此而設的。</p><pre><code>$ ssh -v 192.168.0.103
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/02/ssh_v.png" alt="debug ssh connection"></p><h4 id="_7-綁定源地址" tabindex="-1">7. 綁定源地址 <a class="header-anchor" href="#_7-綁定源地址" aria-label="Permalink to “7. 綁定源地址”">​</a></h4><p>如果你的客户端有多於兩個以上的 IP 地址，你就不可能分得清楚在使用哪一個 IP 連接到 SSH 服務器。</p><p><img src="http://linoxide.com/wp-content/uploads/2014/02/ifconfig.png" alt="More than 1 IP Address"></p><p>為了解決這種情況，我們可以使用 <strong>-b</strong> 選項來指定一個IP 地址。這個 IP 將會被使用做建立連接的源地址。</p><pre><code>$ ssh -b 192.168.0.200 -l leni 192.168.0.103
</code></pre><p>服務端，我們可以使用 netstat 命令來檢查到服務的連接是否建立。可以看到 IP 為 192.168.0.200 的連接已經建立。</p><p><img src="http://linoxide.com/wp-content/uploads/2014/02/ssh_bind.png" alt="Bind address using SSH"></p><h4 id="_8-使用其他配置文件" tabindex="-1">8. 使用其他配置文件 <a class="header-anchor" href="#_8-使用其他配置文件" aria-label="Permalink to “8. 使用其他配置文件”">​</a></h4><p>默認情況下，ssh 會使用位於 <strong>/etc/ssh/ssh_config</strong> 的配置文件。這個配置文件作用於系統的所有用户。但你想要為特定的用户指定特殊的設置的話，可以把配置放入 <strong>~/.ssh/config</strong> 文件中。如果此文件不存在，可以手工創建一個。</p><p>下面是一個通用 <strong>ssh_config</strong> 文件配置的例子。這配置文件位於 <strong>/home/pungki</strong> 目錄下。</p><pre><code>Host 192.168.0.*
ForwardX11 yes
PasswordAuthentication yes
ConnectTimeout 10
Ciphers aes128-ctr,aes192-ctr,aes256-ctr,arcfour256,arcfour128,aes128-cbc,3des-cbc
Protocol 2
HashKnownHosts yes
</code></pre><p>要使用指定的配置文件，可以使用 <strong>-F</strong> 選項。</p><pre><code>$ ssh -F /home/pungki/my_ssh_config 192.168.0.101
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/02/ssh_F.png" alt="Specify your ssh_config"></p><h3 id="_9-使用-ssh-x11-forwarding" tabindex="-1">9. 使用 SSH X11 Forwarding <a class="header-anchor" href="#_9-使用-ssh-x11-forwarding" aria-label="Permalink to “9. 使用 SSH X11 Forwarding”">​</a></h3><p>某些時候，你可能想把服務端的 X11 應用程序顯示到客户端計算機上，SSH 提供了 <strong>-X</strong> 選項。但要啓用這功能，我們需要做些準備，下面是它的設置：</p><p>在服務器端，你需要使 <strong>/etc/ssh/ssh_config</strong> 文件中的行設置成 <strong>ForwardX11 yes 或者 X11Forwad yes</strong>，以啓用 X11 Forwarding，重啓 SSH 服務程序。</p><p>然後在客户端，輸入 <strong>ssh -X user@host</strong>:</p><pre><code>$ ssh -X leni@192.168.0.101
</code></pre><p>一旦登陸，可以輸入：</p><pre><code>$ echo $DISPLAY
</code></pre><p>來檢查，你應該可以看到向如下所示的</p><pre><code>localhost:10:0
</code></pre><p>隨後就可以運行應用了，僅僅只能輸入應用程序的命令。讓我們試試，比如想運行 xclock 程序，輸入：</p><pre><code>$ xclock
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/02/ssh_Y.png" alt="Use X11 Formading"></p><p>它就運行起來了，xclock 確實是運行在遠端系統的，但它在你的本地系統裏顯示了。</p><p><img src="http://linoxide.com/wp-content/uploads/2014/02/xclock.png" alt="xclock"></p><h4 id="_10-可信任的-x11-轉發" tabindex="-1">10. 可信任的 X11 轉發 <a class="header-anchor" href="#_10-可信任的-x11-轉發" aria-label="Permalink to “10. 可信任的 X11 轉發”">​</a></h4><p>如果你敢肯定你的網絡是安全的，那麼你可以使用<strong>可信任的 X11 轉發機制</strong>。這意味着遠程的 X11 客户端可以完全的訪問源 X11 顯示內容。要使用此功能，可以使用 <strong>-Y</strong> 選項。</p><pre><code>$ ssh -Y leni@192.168.0.101
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/02/ssh_Y1.png" alt="SSH _Y for trusted connection"></p><h3 id="結論" tabindex="-1">結論 <a class="header-anchor" href="#結論" aria-label="Permalink to “結論”">​</a></h3><p>我們相信 SSH 的使用範圍非常之廣。SSH 給用户提供了網絡連接的極大安全性和靈活性。通常我們都會輸入 <strong>man ssh</strong> 和 <strong>man ssh_config</strong> 來顯示它的用户手冊及查看更多的細節。</p><p>（譯註補充：建議使用ssh的協議版本2，因此請修改 ssh_config 文件的 Protocol 字段為：2，而將對協議1的支持取消。）</p><hr>`,89)),r("p",null,[s[1]||(s[1]=e("via: ",-1)),o(n,{href:"http://linoxide.com/linux-command/learn-ssh-connection-options/"},{default:t(()=>[...s[0]||(s[0]=[e("http://linoxide.com/linux-command/learn-ssh-connection-options/",-1)])]),_:1})]),r("p",null,[s[4]||(s[4]=e("譯者：",-1)),o(n,{href:"https://github.com/runningwater"},{default:t(()=>[...s[2]||(s[2]=[e("runningwater",-1)])]),_:1}),s[5]||(s[5]=e(" 校對：",-1)),o(n,{href:"https://github.com/wxy"},{default:t(()=>[...s[3]||(s[3]=[e("wxy",-1)])]),_:1})]),r("p",null,[s[8]||(s[8]=e("本文由 ",-1)),o(n,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[6]||(s[6]=[e("LCTT",-1)])]),_:1}),s[9]||(s[9]=e(" 原創翻譯，",-1)),o(n,{href:"http://linux.cn/"},{default:t(()=>[...s[7]||(s[7]=[e("Linux中國",-1)])]),_:1}),s[10]||(s[10]=e(" 榮譽推出",-1))])])}const H=a(c,[["render",d]]);export{b as __pageData,H as default};
